    for (Integer num : nums) {
      set.add(num);
    }

    for (Integer num : nums) {
      if (!set.contains(num - 1)) {
        int currentElement = num;
        int currentLength = 0;
        while (set.contains(currentElement)) {
          currentElement++;
          currentLength++;
